import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { DashboardComponent } from './dashboard.component';
import { MyInsuranceComponent } from './pages/my-insurance/my-insurance.component';
import { DigitalProductsComponent } from './pages/digital-products/digital-products.component';
import { DigitalServicesComponent } from './pages/digital-services/digital-services.component';
import { NotFoundComponent } from '../shared/components/not-found/not-found.component';

const routes: Routes = [
  {
    path: '',
    component: DashboardComponent,
    children: [
      {
        path: 'my-insurance',
        component: MyInsuranceComponent
      },
      {
        path: 'digital-products',
        component: DigitalProductsComponent
      },
      {
        path: 'digital-services',
        component: DigitalServicesComponent
      },
      {
        path: '**',
        component: NotFoundComponent
      }
    ]
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class DashboardRoutingModule { }
