import { Component, Inject, OnInit } from '@angular/core';
import { MAT_DIALOG_DATA } from '@angular/material/dialog';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { DownloadFileService } from '../../../shared/services/download-file.service';

@Component({
  selector: 'app-frame-modal',
  templateUrl: './frame-modal.component.html',
  styleUrls: ['./frame-modal.component.scss']
})
export class FrameModalComponent implements OnInit {

  safeUrl!: SafeResourceUrl;

  constructor(
    @Inject(MAT_DIALOG_DATA) public data: { base64Pdf: string },
    private sanitizer: DomSanitizer,
    private downloadFileService: DownloadFileService
  ) {}

  ngOnInit(): void {
    this.safeUrl = this.sanitizer.bypassSecurityTrustResourceUrl(`data:application/pdf;base64,${this.data.base64Pdf}`);
  }

  downloadPdf(): void {
    this.downloadFileService.downloadPdfFile( this.data.base64Pdf );
  }
}
