import { Injectable } from "@angular/core";
import { Router } from "@angular/router";
import { HttpErrorResponse } from '@angular/common/http';
import { Store } from "@ngrx/store";
import { Actions, concatLatestFrom, createEffect, ofType } from "@ngrx/effects";
import { catchError, map, mergeMap, of, tap } from "rxjs";
import { TokenActions, TokenSelectors } from "../../../shared/store";
import { SnackBarService } from '../../../shared/services/snack-bar.service';
import { InsuranceService } from "../../services/insurance.service";
import { InsuredActions } from "..";

@Injectable()
export class InsuredEffects {

  constructor(
    private store: Store,
    private actions$: Actions,
    private router: Router,
    private insuredService: InsuranceService,
    private snackBarService: SnackBarService,
  ) {}

  loadInsurance$ = createEffect(() => this.actions$.pipe(
    ofType( InsuredActions.loadInsurance ),
    concatLatestFrom( () => this.store.select( TokenSelectors.token ) ),
    mergeMap(([ _, token ]) => this.insuredService.getInsuranceData(token!).pipe(
      map( ({customer, maximumProtectionInsurance, familyLifeInsurance, oncologicalInsurance, xsInsurance, sapInsurance}) => InsuredActions.loadedInsurance({
        customer,
        maximumProtectionInsurance,
        familyLifeInsurance,
        oncologicalInsurance,
        xsInsurance,
        sapInsurance,
      }) ),
      catchError( (httpError: HttpErrorResponse) =>  of(InsuredActions.loadInsuranceFailure({ httpStatus: httpError.status, error: httpError.error?.message })))
    ))
  ));

  loadInsuranceFailure$ = createEffect(() => this.actions$.pipe(
    ofType( InsuredActions.loadInsuranceFailure ),
    tap(({ httpStatus, error }) =>  {
      if( httpStatus && httpStatus === 401 ) {
        this.store.dispatch( TokenActions.removeToken() );
        this.store.dispatch( InsuredActions.resetInsurance() );
        this.snackBarService.openSnackBar('Acceso no autorizado. Por favor, vuelva a autenticarse para continuar.');
        this.router.navigate(['/login']);
        return;
      }
      this.snackBarService.openSnackBar(error);
    })
  ), { dispatch: false });

}
