import { Component, OnInit } from '@angular/core';
import { Store } from '@ngrx/store';
import { InsuredActions, InsuredSelectors } from '../../store';

@Component({
  selector: 'app-insurance-panel',
  templateUrl: './insurance-panel.component.html',
  styleUrls: ['./insurance-panel.component.scss']
})
export class InsurancePanelComponent implements OnInit {
  maximumProtectionInsurance$ = this.store.select( InsuredSelectors.maximumProtectionInsurance );
  familyLifeInsurance$ = this.store.select( InsuredSelectors.familyLifeInsurance );
  oncologicalInsurance$ = this.store.select( InsuredSelectors.oncologicalInsurance );
  xsInsurance$ = this.store.select( InsuredSelectors.xsInsurance );
  sapInsurance$ = this.store.select( InsuredSelectors.sapInsurance );
  constructor( private store: Store ) {}

  ngOnInit(): void {
    this.store.dispatch( InsuredActions.loadInsurance() );
  }

}
