import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';

import { DashboardComponent } from './dashboard.component';
import { InsurancePanelComponent } from './components/insurance-panel/insurance-panel.component';
import { InsurancePanelItemComponent } from './components/insurance-panel-item/insurance-panel-item.component';

import { DashboardRoutingModule } from './dashboard-routing.module';
import { MaterialModule } from '../material/material.module';
import { SharedModule } from '../shared/shared.module';
import { StoreModule } from '@ngrx/store';
import { InsuredReducer } from './store';
import { EffectsModule } from '@ngrx/effects';
import { InsuredEffects } from './store/effects/insured.effects';
import { MyInsuranceComponent } from './pages/my-insurance/my-insurance.component';
import { DigitalProductsComponent } from './pages/digital-products/digital-products.component';
import { DigitalServicesComponent } from './pages/digital-services/digital-services.component';
import { FrameModalComponent } from './components/frame-modal/frame-modal.component';


@NgModule({
  declarations: [
    DashboardComponent,
    InsurancePanelComponent,
    InsurancePanelItemComponent,
    MyInsuranceComponent,
    DigitalProductsComponent,
    DigitalServicesComponent,
    FrameModalComponent,
  ],
  imports: [
    CommonModule,
    DashboardRoutingModule,
    MaterialModule,
    SharedModule,
    StoreModule.forFeature( InsuredReducer.insuredActionReducerKey, InsuredReducer.insuredReducer ),
    EffectsModule.forFeature([ InsuredEffects ]),
  ]
})
export class DashboardModule { }
