import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { map, Observable } from 'rxjs';
import { GetInsuranceDataResponse, ReprintInsuranceCertificateRequest, ReprintInsuranceCertificateResponse } from '../interfaces';
import { BaseResponse } from '../../shared/interface/index';
import { environment } from '../../../environments/environment';


@Injectable({
  providedIn: 'root'
})
export class InsuranceService {

  private baseApiUrl = environment.API_ENDPOINT + environment.INSURANCE_API;

  constructor( private http: HttpClient ) { }

  getInsuranceData( token: string ): Observable<GetInsuranceDataResponse> {
    return this.http.post<BaseResponse<GetInsuranceDataResponse>>(this.baseApiUrl + '/getInsuranceData', {}, this.getHeadersForToken(token))
            .pipe(
              map( resp => resp.result )
            );
  }

  reprintInsuranceCertificate( body: ReprintInsuranceCertificateRequest, token: string ): Observable<string> {
    return this.http.post<BaseResponse<ReprintInsuranceCertificateResponse>>(this.baseApiUrl + '/reprintInsuranceCertificate', body, this.getHeadersForToken(token))
            .pipe(
              map( resp => resp.result.certificate )
            );
  }

  getHeadersForToken( token: string ): { headers: HttpHeaders } {
    const headers = new HttpHeaders({
      'Authorization': `Bearer ${token}`,
    });

    return { headers };
  }

}
