import { Component, Input, OnInit, ViewChild } from '@angular/core';
import { Insured, TableInsured } from '../../interfaces';
import { MatTable } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatDialog } from '@angular/material/dialog';
import { FrameModalComponent } from '../frame-modal/frame-modal.component';
import { DownloadFileService } from '../../../shared/services/download-file.service';
import { InsuranceService } from '../../services/insurance.service';
import { Store } from '@ngrx/store';
import { TokenSelectors } from 'src/app/shared/store';
import { catchError, of, switchMap, take, tap } from 'rxjs';
import { SidenavService } from '../../../shared/services/sidenav.service';
import { HttpErrorResponse } from '@angular/common/http';
import { InsuredActions } from '../../store';

@Component({
  selector: 'app-insurance-panel-item',
  templateUrl: './insurance-panel-item.component.html',
  styleUrls: ['./insurance-panel-item.component.scss']
})
export class InsurancePanelItemComponent implements OnInit{

  @Input() insurance: Insured[] = [];
  @ViewChild(MatTable) table!: MatTable<TableInsured>;
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  dataSource: TableInsured[] = []
  displayedColumns: string[] = ['NO.', 'TITULAR', 'CÉDULA DE IDENTIDAD', 'FECHA AFILIACIÓN', 'OPCIONES'];

  constructor(
    private dialog: MatDialog,
    private store: Store,
    private downloadFileService: DownloadFileService,
    private insuranceService: InsuranceService,
    private sidenavService: SidenavService
  ) {}

  get isMobile() {
    return this.sidenavService.isMobile
  }

  ngOnInit(): void {
    this.dataSource = this.insurance.map( (insured, index) => ({
      number: index + 1,
      userCode: insured.userCode!,
      fullName: insured.fullName,
      document: insured.document,
      insuredCode: insured.insuredCode,
      certificateNumber: insured.certificateNumber,
      affiliationDate: insured.affiliationDate
    }));
  }


  certificateActions( insured: TableInsured, option: 'V' | 'D' ) {
    const { insuredCode, certificateNumber } = insured;
    this.store.select(TokenSelectors.token).pipe(
      take(1),
      switchMap(token =>  this.insuranceService.reprintInsuranceCertificate({ insuredCode, certificateNumber }, token!)),
      tap(certificate => {

        if (option === 'V') {
          this.dialog.open(FrameModalComponent, {
            data: { base64Pdf: certificate },
            width: '80%',
            disableClose: true,
            hasBackdrop: true,
            backdropClass: 'blurred-backdrop',
            panelClass: 'transparent-dialog-panel',
          });
        }

        if (option === 'D') {
          this.downloadFileService.downloadPdfFile(certificate);
        }

      }),
      catchError( (error: HttpErrorResponse) => {
        this.store.dispatch( InsuredActions.loadInsuranceFailure({ httpStatus: error.status, error: error.error?.message }) )
        return of(null)
      })
    ).subscribe();

  }


}
